def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    def is_valid_combination(a, b, c):
        digits = str(a) + str(b) + str(c)
        return len(set(digits)) == 9 and '0' not in digits

    combinations = []
    for i in range(100, 1000):
        j = i * 2
        k = i * 3
        if 100 <= j < 1000 and 100 <= k < 1000:
            if is_valid_combination(i, j, k):
                combinations.append((i, j, k))

    return sorted(combinations)

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: str - A string representing the number string.
    :param N: int - An integer representing the length of the number string.
    :param K: int - An integer representing the number of multiplication signs to insert.
    :return: int - The maximum product that can be obtained.
    """
    if not num_str or N <= 0 or K <= 0 or K >= N:
        return 0

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            if part:
                product *= int(part)
        return product

    def generate_splits(start, k, parts):
        if k == 0:
            parts.append(num_str[start:])
            yield parts
            parts.pop()
            return
        for end in range(start + 1, N - k + 1):
            parts.append(num_str[start:end])
            yield from generate_splits(end, k - 1, parts)
            parts.pop()

    max_product = 0
    for split in generate_splits(0, K, []):
        max_product = max(max_product, split_and_multiply(split))

    return max_product

