def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] represents the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1  # Starting point

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0] % (10**9 + 7)

def max_energy(beads):
    n = len(beads)
    beads = beads + beads[:-1]  # Duplicate the beads list to simulate circular nature
    dp = [[[0] * n for _ in range(n)] for _ in range(2 * n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            if j >= 2 * n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return max(dp[i][i + n - 1] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if degree == 0:
            term = str(abs_coeff)
        elif degree == 1:
            term = 'x' if abs_coeff == 1 else f'{abs_coeff}x'
        else:
            term = 'x^' + str(degree) if abs_coeff == 1 else f'{abs_coeff}x^{degree}'

        if terms:
            terms.append(sign + term)
        else:
            if coeff < 0:
                terms.append('-' + term)
            else:
                terms.append(term)

    return ''.join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Calculate the number of applicants to consider for the interview
    cutoff_index = (m * 150) // 100

    # Sort applicants by test score in descending order, then by registration number in ascending order
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine the interview score cutoff
    if cutoff_index > n:
        cutoff_index = n
    if cutoff_index == 0:
        return (0, [])

    cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Select all applicants with scores equal to or higher than the cutoff score
    qualified_applicants = [applicant for applicant in sorted_applicants if applicant[1] >= cutoff_score]

    return (cutoff_score, qualified_applicants)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reversed_mapping = {}

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

        if orig_char in reversed_mapping:
            if reversed_mapping[orig_char] != enc_char:
                return "Failed"
        else:
            reversed_mapping[orig_char] = enc_char

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return "".join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x, start):
        if k == 1:
            return 1 if n >= x else 0
        count = 0
        for i in range(start, (n // k) + 1):
            if i >= x:
                count += helper(n - i, k - 1, x, i)
        return count

    if n < k * x:
        return 0
    return helper(n, k, x, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last <= 0:
        return 0
    if last in memo:
        return memo[last]
    if last == n:
        count = 1
        for i in range(1, (last // 2) + 1):
            count += count_sequences(n, i, memo)
    else:
        count = 0
        for i in range(1, (last // 2) + 1):
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
    x0 (int): The GCD that each pair (P, Q) must have.
    y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
    int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    if x0 == 0 or y0 == 0 or y0 % x0 != 0:
        return 0

    count = 0
    target = y0 // x0

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    for a in range(1, int(target**0.5) + 1):
        if target % a == 0:
            b = target // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    # BFS setup
    queue = deque([(A, 0)])  # (current_string, steps)
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    # Perform transformation
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                else:
                    break
                start = pos + 1

    return 'NO ANSWER!'

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        is_liar = participant in liar_count
        for statement in participant_statements:
            if statement in days_of_week:
                continue
            if statement.startswith("I am guilty."):
                if (participant == scenario and is_liar) or (participant != scenario and not is_liar):
                    return False
            elif statement.endswith("is guilty."):
                suspect = statement.split()[0]
                if (suspect == scenario and not is_liar) or (suspect != scenario and is_liar):
                    return False
            elif statement.endswith("is not guilty."):
                suspect = statement.split()[0]
                if (suspect == scenario and is_liar) or (suspect != scenario and not is_liar):
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("System must be either 11 or 21 points.")

    if not isinstance(points, str) or any(char not in 'WL' for char in points):
        raise ValueError("Points must be a string containing only 'W' and 'L'.")

    player_score = 0
    opponent_score = 0
    scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0

    # Create a set to represent the positions of all trees
    trees = set(range(l))

    # Process each area and remove the trees in that range
    for start, end in areas:
        if start <= end:
            for pos in range(max(0, start), min(l, end) + 1):
                if pos in trees:
                    trees.remove(pos)

    # The number of remaining trees is the size of the set
    return len(trees)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store whether a particular volume is achievable
    dp = [False] * (V + 1)
    dp[0] = True  # Zero volume is always achievable

    # Iterate over each volume
    for volume in volumes:
        # Update the dp array from back to front
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_achievable_volume = j
            break

    # Return the remaining space
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0

    for i, (school_hours, extra_hours) in enumerate(schedule):
        total_hours = school_hours + extra_hours
        unhappiness = total_hours - 8 if total_hours > 8 else 0

        if unhappiness > max_unhappiness:
            max_unhappiness = unhappiness
            most_unhappy_day = i + 1

    return most_unhappy_day

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    # Base case for 1 pair of discs
    moves = 2

    # Iteratively calculate the number of moves for n pairs
    for i in range(2, n + 1):
        moves = 2 * moves + 2

    return moves
